#include <iostream>
#include <memory>
#include <functional>
#include <vector>
#include <chrono>
#include <string>
#include <mutex>

enum class CircuitState { CLOSED, OPEN, HALF_OPEN };

class ServiceCall {
public:
    std::string endpoint;
    std::function<void(const std::string&)> on_complete;

    ServiceCall(const std::string& ep) : endpoint(ep) {}
    virtual ~ServiceCall() = default;
    virtual bool execute() = 0;
};

class HttpCall : public ServiceCall {
    std::string response_buffer_;
public:
    HttpCall(const std::string& ep) : ServiceCall(ep) {}
    bool execute() override {
        response_buffer_ = "HTTP 200 OK from " + endpoint;
        if (on_complete) on_complete(response_buffer_);
        return true;
    }
};

class CircuitBreaker {
    CircuitState state_ = CircuitState::CLOSED;
    int failure_count_ = 0;
    int failure_threshold_;
    int success_count_ = 0;
    int success_threshold_;
    std::vector<ServiceCall*> pending_calls_;
    std::mutex mtx_;

    struct CallRecord {
        ServiceCall* call;
        std::chrono::steady_clock::time_point timestamp;
    };
    std::vector<CallRecord> history_;

public:
    CircuitBreaker(int fail_thresh = 3, int success_thresh = 2)
        : failure_threshold_(fail_thresh), success_threshold_(success_thresh) {}

    bool submit(ServiceCall* call) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (state_ == CircuitState::OPEN) {
            std::cout << "Circuit OPEN - rejecting call to " << call->endpoint << std::endl;
            return false;
        }
        pending_calls_.push_back(call);
        history_.push_back({call, std::chrono::steady_clock::now()});
        return true;
    }

    void process_pending() {
        std::lock_guard<std::mutex> lock(mtx_);
        std::vector<ServiceCall*> to_process;
        std::swap(to_process, pending_calls_);

        for (auto* call : to_process) {
            bool success = false;
            try {
                success = call->execute();
            } catch (...) {
                success = false;
            }

            if (success) {
                on_success();
            } else {
                on_failure();
            }
        }
    }

    void drain_and_retry() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (state_ == CircuitState::OPEN) {
            state_ = CircuitState::HALF_OPEN;
            success_count_ = 0;
            std::cout << "Circuit transitioning to HALF_OPEN" << std::endl;

            // Retry last recorded calls from history
            for (auto& record : history_) {
                try {
                    record.call->execute();
                } catch (...) {
                    state_ = CircuitState::OPEN;
                    return;
                }
            }
            state_ = CircuitState::CLOSED;
            failure_count_ = 0;
            history_.clear();
        }
    }

    CircuitState get_state() const { return state_; }

private:
    void on_success() {
        if (state_ == CircuitState::HALF_OPEN) {
            success_count_++;
            if (success_count_ >= success_threshold_) {
                state_ = CircuitState::CLOSED;
                failure_count_ = 0;
                history_.clear();
            }
        }
    }

    void on_failure() {
        failure_count_++;
        if (failure_count_ >= failure_threshold_) {
            state_ = CircuitState::OPEN;
            std::cout << "Circuit OPEN after " << failure_count_ << " failures" << std::endl;
        }
    }
};

class CommandProcessor {
    CircuitBreaker breaker_;
    std::vector<std::unique_ptr<ServiceCall>> owned_calls_;

public:
    CommandProcessor() : breaker_(3, 2) {}

    void handle_request(const std::string& endpoint) {
        auto call = std::make_unique<HttpCall>(endpoint);
        call->on_complete = [this](const std::string& resp) {
            std::cout << "Response: " << resp << std::endl;
        };
        breaker_.submit(call.get());
        owned_calls_.push_back(std::move(call));
    }

    void execute_all() {
        breaker_.process_pending();
    }

    void reset_calls() {
        owned_calls_.clear();
    }

    void attempt_recovery() {
        breaker_.drain_and_retry();
    }
};

int main(int argc, char* argv[]) {
    CommandProcessor processor;
    std::string line;

    std::cout << "Circuit Breaker CLI (commands: call <ep>, exec, reset, recover, quit)" << std::endl;

    while (std::getline(std::cin, line)) {
        if (line.substr(0, 4) == "call") {
            std::string ep = line.length() > 5 ? line.substr(5) : "default";
            processor.handle_request(ep);
        } else if (line == "exec") {
            processor.execute_all();
        } else if (line == "reset") {
            processor.reset_calls();
        } else if (line == "recover") {
            processor.attempt_recovery();
        } else if (line == "quit") {
            break;
        }
    }
    return 0;
}
